//! Byte-exact agreement with the vendor oracle (`dectris.compression 0.3.1`, liblz4 + bitshuffle
//! inside) on streams produced by the vendor encoders (hdf5plugin 6.0.0). DESIGN §8 Tier 1, §9 Phase 1.
//!
//! * committed vectors (`tests/vectors/oracle_*.bin`, generated by `tests/gen_vectors.py all`):
//!   u8/u16/u32, odd shapes, leftover-only, partial last block, multi-block, 1-byte lz4 blocks;
//! * trailing-junk vectors with the oracle's recorded verdict (we reject all; the oracle accepts
//!   most — the deliberate divergence of DESIGN §4.5);
//! * large cases regenerated at test time with the Python of `DECTRIS_TEST_PYTHON` (sha256-checked), skipped when
//!   Python is unavailable;
//! * a live differential batch: thousands of truncated / corrupted streams decoded by both this
//!   crate and the oracle (skipped without Python).

#![allow(clippy::unwrap_used, clippy::expect_used)] // test code (clippy.toml exempts #[test] fns only, not helpers)

mod common;

use std::collections::BTreeMap;
use std::fs;

use common::{pattern_bytes, python, regen_dir, run_gen, vectors_dir};
use dectris_codec::encode::{compress_bslz4, compress_lz4};
use dectris_codec::framing::{self, Algorithm};
use dectris_common::DriverError;

fn alg(s: &str) -> Algorithm {
    Algorithm::from_wire(s.as_bytes()).unwrap()
}

fn manifest(name: &str) -> Vec<Vec<String>> {
    let text = fs::read_to_string(vectors_dir().join(name)).unwrap();
    text.lines()
        .filter(|l| !l.starts_with('#') && !l.trim().is_empty())
        .map(|l| l.split_whitespace().map(str::to_owned).collect())
        .collect()
}

fn slice(container: &str, off: &str, len: &str, cache: &mut BTreeMap<String, Vec<u8>>) -> Vec<u8> {
    let blob = cache
        .entry(container.to_owned())
        .or_insert_with(|| fs::read(vectors_dir().join(container)).unwrap());
    let (o, l): (usize, usize) = (off.parse().unwrap(), len.parse().unwrap());
    blob[o..o + l].to_vec()
}

#[test]
fn committed_oracle_vectors_byte_exact() {
    let rows = manifest("oracle.manifest");
    assert!(
        rows.len() >= 200,
        "need >= 200 oracle vectors, have {}",
        rows.len()
    );
    let mut cache = BTreeMap::new();
    let (mut multi_block, mut leftover, mut partial) = (0, 0, 0);
    for r in &rows {
        // name algo elem pattern seed n_elems block_param container offset length
        let (name, a, elem, pattern, seed, n) = (
            &r[0],
            &r[1],
            r[2].parse::<usize>().unwrap(),
            &r[3],
            r[4].parse::<u64>().unwrap(),
            r[5].parse::<usize>().unwrap(),
        );
        let stream = slice(&r[7], &r[8], &r[9], &mut cache);
        let want = pattern_bytes(pattern, seed, n, elem);
        let got = framing::decompress(alg(a), elem as u64, &stream)
            .unwrap_or_else(|e| panic!("{name}: {e}"));
        assert_eq!(got, want, "{name}");
        let h = framing::parse_header(&stream).unwrap();
        let orig = h.orig_size as usize;
        let block = h.block_size as usize;
        if orig > block {
            multi_block += 1;
        }
        if a == "bslz4" && orig % (8 * elem) != 0 {
            leftover += 1;
        }
        if orig % block != 0 {
            partial += 1;
        }
        // the oracle accepts lz4 with any modifier; so do we [R17]
        if a == "lz4" {
            assert_eq!(
                framing::decompress(Algorithm::Lz4, 4, &stream).unwrap(),
                want
            );
        }
    }
    println!("{} oracle vectors: {multi_block} multi-block, {leftover} with bslz4 leftover, {partial} with a partial last block", rows.len());
    assert!(multi_block > 50 && leftover > 20 && partial > 50);
}

#[test]
fn trailing_junk_rejected_where_the_oracle_accepts() {
    let rows = manifest("oracle_junk.manifest");
    let mut cache = BTreeMap::new();
    let mut oracle_ok = 0;
    for r in &rows {
        // name algo elem pattern seed n_elems junk_hex oracle_verdict container offset length
        let (name, a, elem, pattern, seed, n) = (
            &r[0],
            &r[1],
            r[2].parse::<usize>().unwrap(),
            &r[3],
            r[4].parse::<u64>().unwrap(),
            r[5].parse::<usize>().unwrap(),
        );
        let junk = common::unhex(&r[6]);
        let verdict = &r[7];
        let stream = slice(&r[8], &r[9], &r[10], &mut cache);
        match framing::decompress(alg(a), elem as u64, &stream) {
            Err(DriverError::Decode { msg, .. }) => {
                assert!(
                    msg.contains("trailing") || msg.contains("leftover"),
                    "{name}: {msg}"
                );
            }
            other => panic!("{name}: expected rejection, got {other:?}"),
        }
        let clean = &stream[..stream.len() - junk.len()];
        assert_eq!(
            framing::decompress(alg(a), elem as u64, clean).unwrap(),
            pattern_bytes(pattern, seed, n, elem),
            "{name}"
        );
        assert!(
            verdict == "ok" || verdict == "err",
            "{name}: oracle verdict {verdict}"
        );
        if verdict == "ok" {
            oracle_ok += 1;
        }
    }
    // the divergence is real: the oracle accepted junk after lz4 streams and bslz4 streams
    // without a leftover tail (compression.c checks the tail only when leftover > 0)
    assert!(oracle_ok >= 10, "oracle accepted {oracle_ok} junk vectors");
}

#[test]
fn regenerated_large_cases_match_oracle() {
    let Some(py) = python() else {
        eprintln!("SKIP regenerated_large_cases_match_oracle: no Python with the oracle packages");
        return;
    };
    let dir = regen_dir("large");
    for r in manifest("regen.manifest") {
        // name algo elem pattern seed n_elems block_param sha256_compressed sha256_output
        let (name, a, elem, pattern, seed, n) = (
            &r[0],
            &r[1],
            r[2].parse::<usize>().unwrap(),
            &r[3],
            r[4].parse::<u64>().unwrap(),
            r[5].parse::<usize>().unwrap(),
        );
        let out = run_gen(&py, &["regen", name, dir.to_str().unwrap()]);
        let shas: Vec<&str> = out.split_whitespace().collect();
        assert_eq!(shas.len(), 2, "{name}: {out}");
        assert_eq!(
            shas[1], r[8],
            "{name}: oracle output sha256 changed (generator drift)"
        );
        if shas[0] != r[7] {
            eprintln!("WARNING {name}: compressed sha256 {} != manifest {} (hdf5plugin/liblz4 version change?)", shas[0], r[7]);
        }
        let stream = fs::read(dir.join(format!("{name}.bin"))).unwrap();
        let t = std::time::Instant::now();
        let got = framing::decompress(alg(a), elem as u64, &stream).unwrap();
        let dt = t.elapsed();
        assert_eq!(got, pattern_bytes(pattern, seed, n, elem), "{name}");
        println!(
            "{name}: {} B -> {} B in {dt:?} (vendor-encoded)",
            stream.len(),
            got.len()
        );
    }
}

// ---- live differential batch ----

fn push_record(batch: &mut Vec<u8>, a: Algorithm, elem: u32, stream: &[u8]) {
    batch.push(match a {
        Algorithm::Bslz4 => 0,
        Algorithm::Lz4 => 1,
    });
    batch.extend_from_slice(&elem.to_le_bytes());
    batch.extend_from_slice(&(stream.len() as u32).to_le_bytes());
    batch.extend_from_slice(stream);
}

fn parse_results(b: &[u8]) -> Vec<Result<Vec<u8>, String>> {
    let mut v = Vec::new();
    let mut p = 0;
    while p < b.len() {
        let st = b[p];
        let n = u32::from_le_bytes(b[p + 1..p + 5].try_into().unwrap()) as usize;
        let body = b[p + 5..p + 5 + n].to_vec();
        p += 5 + n;
        v.push(if st == 0 {
            Ok(body)
        } else {
            Err(String::from_utf8_lossy(&body).into_owned())
        });
    }
    v
}

/// True if lz4_flex rejects some block of the stream (blocks walked leniently).
fn lz4_flex_rejects(a: Algorithm, c: &[u8]) -> bool {
    let h = framing::parse_header(c).unwrap();
    let mut p = 12;
    let mut left = h.orig_size as usize;
    while p + 4 <= c.len() && left > 0 {
        let n = u32::from_be_bytes(c[p..p + 4].try_into().unwrap()) as usize;
        let size = left.min(h.block_size as usize);
        let Some(blk) = c.get(p + 4..p + 4 + n) else {
            return true;
        };
        if !(a == Algorithm::Lz4 && n == size) {
            let mut out = vec![0u8; size];
            if lz4_flex::block::decompress_into(blk, &mut out).is_err() {
                return true;
            }
        }
        p += 4 + n;
        left -= size;
    }
    false
}

#[test]
fn differential_corruption_vs_oracle() {
    let Some(py) = python() else {
        eprintln!("SKIP differential_corruption_vs_oracle: no Python with the oracle packages");
        return;
    };
    // base streams: vendor-encoded committed vectors (multi-block) + this crate's encoder
    let mut cache = BTreeMap::new();
    let mut bases: Vec<(Algorithm, u32, Vec<u8>)> = Vec::new();
    for r in manifest("oracle.manifest") {
        let n: usize = r[5].parse().unwrap();
        let elem: usize = r[2].parse().unwrap();
        if (64..=1200).contains(&(n * elem)) && r[3] != "zeros" && bases.len() < 24 {
            bases.push((
                alg(&r[1]),
                elem as u32,
                slice(&r[7], &r[8], &r[9], &mut cache),
            ));
        }
    }
    let data: Vec<u8> = common::pattern_bytes("low", 99, 600, 2);
    bases.push((Algorithm::Bslz4, 2, compress_bslz4(&data, 2, 256).unwrap()));
    bases.push((Algorithm::Lz4, 0, compress_lz4(&data, 300).unwrap()));

    let mut batch = Vec::new();
    let mut cases: Vec<(Algorithm, u32, Vec<u8>)> = Vec::new();
    let mut s = 0x00C0_FFEE_u64;
    for (a, e, base) in &bases {
        // truncation at every offset
        for cut in 0..base.len() {
            cases.push((*a, *e, base[..cut].to_vec()));
        }
        // one flip at every byte position, two different masks
        for i in 0..base.len() {
            for mask in [0x01u8, 0x80] {
                let mut c = base.clone();
                c[i] ^= mask;
                cases.push((*a, *e, c));
            }
        }
        // random multi-byte corruption of the payload
        for _ in 0..40 {
            let mut c = base.clone();
            for _ in 0..3 {
                s = s
                    .wrapping_mul(6364136223846793005)
                    .wrapping_add(1442695040888963407);
                let i = 12 + (s >> 33) as usize % (c.len().saturating_sub(12).max(1));
                if i < c.len() {
                    c[i] = (s >> 13) as u8;
                }
            }
            cases.push((*a, *e, c));
        }
    }
    for (a, e, c) in &cases {
        push_record(
            &mut batch,
            *a,
            (*e).max(if *a == Algorithm::Bslz4 { 1 } else { 0 }),
            c,
        );
    }
    let dir = regen_dir("differential");
    let inp = dir.join("batch.in");
    let outp = dir.join("batch.out");
    fs::write(&inp, &batch).unwrap();
    run_gen(
        &py,
        &[
            "oracle-batch",
            inp.to_str().unwrap(),
            outp.to_str().unwrap(),
        ],
    );
    let results = parse_results(&fs::read(&outp).unwrap());
    assert_eq!(results.len(), cases.len());

    let (mut both_ok, mut both_err, mut trailing_div, mut zero_offset_div) =
        (0usize, 0usize, 0usize, 0usize);
    for ((a, e, c), oracle) in cases.iter().zip(results) {
        let elem = (*e).max(if *a == Algorithm::Bslz4 { 1 } else { 0 }) as u64;
        let mine = framing::decompress(*a, elem, c);
        match (&mine, &oracle) {
            (Ok(m), Ok(o)) => {
                assert_eq!(m, o, "{a} output differs for {}", common::hex(c));
                both_ok += 1;
            }
            (Err(_), Err(_)) => both_err += 1,
            (Err(DriverError::Decode { msg, .. }), Ok(_)) if msg.contains("trailing bytes") => {
                trailing_div += 1
            }
            // the oracle's liblz4 accepts match offset 0 (invalid per the LZ4 block format) and
            // copies uninitialised scratch; lz4_flex rejects it too
            (Err(DriverError::Decode { msg, .. }), Ok(_))
                if msg.contains("invalid match offset 0") =>
            {
                assert!(
                    lz4_flex_rejects(*a, c),
                    "lz4_flex accepted the offset-0 stream"
                );
                zero_offset_div += 1
            }
            (Err(err), Ok(_)) => panic!(
                "we reject what the oracle accepts ({a}, elem {elem}): {err}\n{}",
                common::hex(c)
            ),
            (Ok(_), Err(oe)) => panic!(
                "we accept what the oracle rejects ({a}, elem {elem}): {oe}\n{}",
                common::hex(c)
            ),
        }
    }
    println!(
        "differential: {} cases, {both_ok} both ok (identical bytes), {both_err} both rejected, {trailing_div} trailing-bytes divergences (DESIGN §4.5), {zero_offset_div} LZ4 offset-0 divergences (oracle reads uninitialised memory)",
        cases.len()
    );
    assert!(both_ok > 100 && both_err > 1000);
}
